          code: "# 教学示例：仅在本地测试环境运行，不要对真实业务数据使用。\n# 依赖 pycryptodome：pip install pycryptodome\n# 也可以用标准库之外的任何实现替换，重点是观察两种模式的差异。\n\nfrom Crypto.Cipher import AES\nfrom Crypto.Util.Padding import pad\n\n\nkey = bytes.fromhex('00112233445566778899aabbccddeeff')   # 128 位密钥\n\n# 两块完全相同的 16 字节明文，正是「结构化数据」的典型形态：\n# 工资表里两条薪资相同的记录，或同一个用户的两个 Cookie 字段。\nblock = b'salary=1000000!a'\nplain = block + block + b'user=alice_00000'\n\n\ndef ecb_encrypt(data):\n    c = AES.new(key, AES.MODE_ECB)\n    return c.encrypt(pad(data, 16))\n\n\ndef cbc_encrypt(data, iv):\n    c = AES.new(key, AES.MODE_CBC, iv)\n    return c.encrypt(pad(data, 16))\n\n\nct_ecb = ecb_encrypt(plain)\niv = bytes(range(16))                       # 演示用固定 IV，生产环境必须每次随机\nct_cbc = cbc_encrypt(plain, iv)\n\nprint('明文块 1 :', plain[0:16])\nprint('明文块 2 :', plain[16:32], '  <- 与块 1 完全相同')\nprint()\nprint('ECB 块 1 :', ct_ecb[0:16].hex())\nprint('ECB 块 2 :', ct_ecb[16:32].hex())\nprint('ECB 两块密文相同吗:', ct_ecb[0:16] == ct_ecb[16:32], '  <- True 就是缺陷本身')\nprint()\nprint('CBC 块 1 :', ct_cbc[0:16].hex())\nprint('CBC 块 2 :', ct_cbc[16:32].hex())\nprint('CBC 两块密文相同吗:', ct_cbc[0:16] == ct_cbc[16:32], '  <- False 才是安全的')\n\n# 结论：CBC 通过「与前一块密文异或」把相同明文打散。\n# 攻击者即使能看到密文，也无法判断两块明文是否相同。\n# 但 CBC 仍需注意：IV 必须随机、解密失败必须统一报错（否则触发 padding oracle）。",
