          title: "栈溢出最小复现与修复（仅本地测试环境，教学用途）",
          code: "/*\n * 教学用最小复现：仅在本地测试环境编译运行（建议放在虚拟机里做）。\n * 编译：gcc -m32 -fno-stack-protector -z execstack -g overflow_demo.c -o overflow_demo\n * 说明：-fno-stack-protector 关闭栈金丝雀、-z execstack 关闭 DEP，\n *       目的是把漏洞暴露出来便于观察；生产编译绝不允许这样。\n * 运行：./overflow_demo AAAA...（参数长度超过 64 就会破坏栈帧）\n */\n\n#include <stdio.h>\n#include <string.h>\n\n/* ---------- 漏洞版本：无边界检查 ---------- */\nvoid vulnerable(char *input)\n{\n    char buf[64];                 /* 栈上 64 字节缓冲区 */\n    strcpy(buf, input);           /* 危险：不检查长度，直接拷到 buf */\n    printf(\"vulnerable: 收到 %u 字节\\n\", (unsigned)strlen(buf));\n    /*\n     * 当 input 超过 64 字节时，会依次覆盖：\n     *   buf[64] 之后的 4 字节 = 保存的 EBP\n     *   再往后 4 字节         = 返回地址 ← 攻击者最想要的就是这 4 字节\n     * 覆盖返回地址需要写满 64 + 4 + 4 = 72 字节。\n     * 在 x86-64 上偏移量是 64 + 8 + 8 = 80 字节。\n     */\n}\n\n/* ---------- 修复版本 1：限制拷贝长度 ---------- */\nvoid fixed_strncpy(const char *input)\n{\n    char buf[64];\n    strncpy(buf, input, sizeof(buf) - 1);   /* 最多 63 字节，留 1 字节给结束符 */\n    buf[sizeof(buf) - 1] = '\\0';            /* 必须手动保证以 \\0 结尾 */\n    printf(\"fixed_strncpy: 安全截断为 %u 字节\\n\", (unsigned)strlen(buf));\n}\n\n/* ---------- 修复版本 2：拒绝超长输入（业务上通常更合适） ---------- */\nint fixed_checked(const char *input)\n{\n    char buf[64];\n    if (strlen(input) >= sizeof(buf)) {\n        fprintf(stderr, \"fixed_checked: 输入过长，拒绝处理\\n\");\n        return -1;                          /* 明确失败，绝不截断后继续 */\n    }\n    strcpy(buf, input);\n    printf(\"fixed_checked: 接受 %u 字节\\n\", (unsigned)strlen(buf));\n    return 0;\n}\n\nint main(int argc, char **argv)\n{\n    if (argc < 2) {\n        fprintf(stderr, \"用法: %s <字符串>\\n\", argv[0]);\n        return 1;\n    }\n    printf(\"输入长度 = %u 字节（覆盖返回地址需要 72 字节，x86-64 下为 80）\\n\",\n           (unsigned)strlen(argv[1]));\n\n    fixed_strncpy(argv[1]);\n    fixed_checked(argv[1]);\n\n    /* 取消下面这行的注释即可观察崩溃，或配合 gdb 观察 EIP 被改写：\n     * gdb --args ./overflow_demo $(python3 -c \"print('A'*72 + 'BBBB')\")\n     *   在 vulnerable 返回处会看到 EIP = 0x42424242（即 'BBBB'）\n     */\n    /* vulnerable(argv[1]); */\n\n    printf(\"程序正常结束\\n\");\n    return 0;\n}\n\n/*\n * 工程提醒：\n * 1. 生产编译请开启全部加固：\n *    gcc -O2 -fstack-protector-strong -D_FORTIFY_SOURCE=2 -fPIE -pie \\\n *        -Wl,-z,relro,-z,now overflow_demo.c -o overflow_demo\n * 2. 服务进程绝不能以 root 运行，用最小权限账号加容器隔离。\n * 3. 新项目优先选择内存安全语言（Rust / Go / Java），从根上消掉整类漏洞。\n */",
